fn copyto<T: Copy>(dst: Vec<T>, src: Vec<T>, mask: Vec<bool>) -> Vec<T> {
    // Since all arrays have the same length, we can safely iterate by index.
    let len = dst.len();
    let mut result = Vec::with_capacity(len);
    for i in 0..len {
        // If mask[i] is true, choose src[i], otherwise dst[i]
        if mask[i] {
            result.push(src[i]);
        } else {
            result.push(dst[i]);
        }
    }
    result
}